import {NextRequest,NextResponse} from 'next/server';import {db,required,stripe} from '@/lib/core';import {fulfill} from '@/lib/checkout';export const runtime='nodejs';export async function POST(req:NextRequest){let event;try{event=stripe.webhooks.constructEvent(await req.text(),req.headers.get('stripe-signature')||'',required('STRIPE_WEBHOOK_SECRET'))}catch(e){console.warn('webhook_rejected');return new NextResponse('Bad signature',{status:400})}try{const seen=await db.query('INSERT INTO webhook_events(stripe_event_id,type) VALUES($1,$2) ON CONFLICT DO NOTHING RETURNING stripe_event_id',[event.id,event.type]);if(!seen.rowCount)return NextResponse.json({received:true,duplicate:true});if(['checkout.session.completed','checkout.session.async_payment_succeeded'].includes(event.type))await fulfill((event.data.object as any).id);if(event.type==='checkout.session.async_payment_failed'||event.type==='payment_intent.payment_failed')await db.query(`UPDATE checkout_payments SET status='payment_failed',updated_at=now() WHERE stripe_checkout_session_id=$1 OR stripe_payment_intent_id=$1`,[(event.data.object as any).id]);if(event.type==='charge.refunded'){const ch=event.data.object as any;await db.query(`UPDATE checkout_payments SET status=$1,updated_at=now() WHERE stripe_payment_intent_id=$2`,[ch.refunded?'refunded':'partially_refunded',ch.payment_intent])}return NextResponse.json({received:true})}catch(e){await db.query('DELETE FROM webhook_events WHERE stripe_event_id=$1',[event.id]);console.error('webhook_failed',{eventId:event.id,error:e instanceof Error?e.message:'unknown'});return new NextResponse('Retry',{status:500})}}
